import json, sys, html as _h

BOOK = {'title': 'The kingdom of Eldoria Chronicles', 'author': 'Signature original', 'genre': 'Dwarven Kingdoms', 'chapters': [{'n': 1, 'title': 'The Call', 'text': "the wizard Old Fenwick arrived with a pack, a sword, and no patience for goodbyes. 'You're the one the songs mean,' the wizard Old Fenwick said. 'the Crystal of Dawn chose you. Don't argue with songs.'\n\nSeraphina Moon was mending a fence in the kingdom of Eldoria when the sky went dark at noon. The elders whispered: the Dark Lord Malachar had taken the Crystal of Dawn, and the old magic was failing. Prophecy or not, someone had to go.\n\nThey left the kingdom of Eldoria at dusk, the road winding into the unknown. Behind them, lights went out one by one as the Dark Lord Malachar's shadow spread. Ahead: everything."}, {'n': 2, 'title': 'Trials of the Road', 'text': "The road through the kingdom of Eldoria tested them daily: a bridge held by a troll who demanded riddles, a forest where the trees walked, a river that flowed uphill. the wizard Old Fenwick's wit and Seraphina Moon's courage saw them through each.\n\nWounded and weary, they sheltered with griffon-riders who told tales of the Dark Lord Malachar's cruelty. Every tale ended the same: no one had faced the Dark Lord Malachar and lived. Seraphina Moon listened, and was afraid, and went on anyway.\n\nThey were ambushed by the Dark Lord Malachar's riders at the enchanted glade. Seraphina Moon fought with a mithril blade borrowed from the wizard Old Fenwick, and learned that bravery is mostly refusing to run at the right moment."}, {'n': 3, 'title': 'The Descent', 'text': "the Crystal of Dawn blazed at Seraphina Moon's touch, recognizing its bearer. Power flooded through them — and with it, the terrible knowledge of its price. Every magic, the seer had said, is a promise. This one demanded everything.\n\nAlarms rang. the Dark Lord Malachar's army closed in. the wizard Old Fenwick barred the door with a fallen pillar and grinned. 'Go,' they said. 'I'll hold them.' Seraphina Moon refused to leave — so they held it together, back to back, as the dark came on.\n\nThey found the Crystal of Dawn in the vault of whispers, guarded by the dragon Karthax. The beast spoke: 'Take it, little bearer, if you can answer: what is stronger than dragonfire?' Seraphina Moon answered: 'unity defeats darkness.' The dragon bowed and let them pass."}, {'n': 4, 'title': 'The Price', 'text': "the wizard Old Fenwick woke and wept to see it. 'The prophecy—' they began. Seraphina Moon said: 'Prophecies are poems, not orders.' But the army of the Dark Lord Malachar was coming, and they had no magic left.\n\nSeraphina Moon did not hesitate. They laid the Crystal of Dawn on the wizard Old Fenwick's chest, and the light went into the wound, and the wound closed — and the Crystal of Dawn went dark and cold. The quest's great weapon, spent on one life.\n\nThey escaped the fortress by griffon, the Crystal of Dawn burning like a small sun. But the wizard Old Fenwick was wounded, and the wound festered with dark magic. The healers said only the Crystal of Dawn itself could cure it — at the cost of its power."}, {'n': 5, 'title': 'The Breaking of the Dark', 'text': 'The battle for the kingdom of Eldoria raged from dawn to dusk. the Dark Lord Malachar rode out in black armor, terrible and splendid, and challenged Seraphina Moon single combat. The armies held their breath.\n\nSeraphina Moon fought with the mithril blade and no magic at all — only skill, and love of the kingdom of Eldoria, and the wizard Old Fenwick shouting from the lines. the Dark Lord Malachar fought with hate and sorcery, and for a long while hate seemed stronger.\n\nThe army of the dark broke and ran. the kingdom of Eldoria was free. Seraphina Moon stood in the sudden silence holding the Crystal of Dawn, which was only a crystal again — but a crystal that had kept its promise.'}, {'n': 6, 'title': 'The Return', 'text': "the Crystal of Dawn was set in the great hall, where children touch it for luck. It never blazed again — but on dark nights, travelers swear it glows faintly, like a coal that remembers fire.\n\nthe wizard Old Fenwick was given the highest honor of the kingdom of Eldoria and immediately used it to demand better roads. Seraphina Moon was offered a throne and laughed until they cried. 'I mend fences,' Seraphina Moon said.\n\nThey came home to the kingdom of Eldoria in spring, when the orchards bloomed. The songs had already arrived ahead of them, as songs do, and every verse was wrong in the details and right in the heart."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

